def install(apps, editor):
    if editor.connection.vendor == "postgresql":
        for sql in (
            SQL,
            MEMBER_SCOPE,
            FEE_SCOPE,
            COMPLETE_SCOPE,
            CANCELLED_SCOPE,
            UNCOLLECTED_SCOPE,
            CANCELLED_COMPLETE,
        ):
            editor.execute(sql, params=None)
        for table, scope, backed in (
            (
                "membershippaidvisitsplit",
                "monkeydo_paid_visit_split_scope",
                "monkeydo_paid_visit_split_backed",
            ),
            (
                "membershippaidvisitsplitcard",
                "monkeydo_paid_visit_split_card_scope",
                "monkeydo_paid_visit_split_card_backed",
            ),
        ):
            editor.execute(
                f"CREATE TRIGGER core_{table}_immutable BEFORE UPDATE OR DELETE ON core_{table} FOR EACH ROW EXECUTE FUNCTION monkeydo_financial_immutable()"
            )
            editor.execute(
                f"CREATE TRIGGER core_{table}_scope BEFORE INSERT ON core_{table} FOR EACH ROW EXECUTE FUNCTION {scope}()"
            )
            editor.execute(
                f"CREATE CONSTRAINT TRIGGER core_{table}_backed AFTER INSERT ON core_{table} DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION {backed}()"
            )
    elif editor.connection.vendor == "sqlite":
        for table in ("membershippaidvisitsplit", "membershippaidvisitsplitcard"):
            for event in ("UPDATE", "DELETE"):
                editor.execute(
                    f"CREATE TRIGGER core_{table}_{event.lower()}_immutable BEFORE {event} ON core_{table} BEGIN SELECT RAISE(ABORT, 'Split payment evidence is immutable'); END"
                )


def remove(apps, editor):
    if (
        apps.get_model("core", "MembershipPaidVisitSplit")
        .objects.using(editor.connection.alias)
        .exists()
    ):
        raise RuntimeError(
            "Recorded split-remainder payments cannot be reversed. Keep compatible code and fix forward."
        )
    if editor.connection.vendor == "postgresql":
        for table in ("membershippaidvisitsplit", "membershippaidvisitsplitcard"):
            for suffix in ("immutable", "scope", "backed"):
                editor.execute(f"DROP TRIGGER core_{table}_{suffix} ON core_{table}")
        for sql in (
            OLD.MEMBER_SCOPE,
            OLD_FEE,
            OLD.COMPLETE_SCOPE,
            OLD.CANCELLED_SCOPE,
            OLD_UNCOLLECTED,
            OLD_CANCELLED_COMPLETE,
        ):
            editor.execute(sql, params=None)
        for signature in (
            "monkeydo_paid_visit_split_scope()",
            "monkeydo_paid_visit_split_backed()",
            "monkeydo_paid_visit_split_card_scope()",
            "monkeydo_paid_visit_split_card_backed()",
            "monkeydo_paid_visit_split_receipt_allowed(uuid,core_paymentoperation)",
            "monkeydo_paid_visit_split_completed(uuid)",
            "monkeydo_paid_visit_split_fee_matches(core_financiallineadjustment,uuid)",
            "monkeydo_paid_visit_split_method(uuid,uuid)",
        ):
            editor.execute(f"DROP FUNCTION {signature}")
    elif editor.connection.vendor == "sqlite":
        for table in ("membershippaidvisitsplit", "membershippaidvisitsplitcard"):
            for event in ("update", "delete"):
                editor.execute(f"DROP TRIGGER core_{table}_{event}_immutable")


